.tab-title {
    background: #0073aa;
    color: white;
    border: none;
    padding: 10px;
    width: 100%;
    text-align: left;
    cursor: pointer;
    font-size: 16px;
    margin: 5px 0;
}

.tab-title:hover {
    background: #005177;
}

.widget-wrapper:not(.active) .widget.widget_nav_menu > div {
    display: none;
    padding: 30px 0 0;
}

.widget-wrapper.active .widget.widget_nav_menu > div {
    padding: 30px 0 0;
    display: block;

}


.widget-wrapper p.widget-title:after {
    content: "\e919";
    right:20px;
    font-size: 30px;
    font-family: 'misceladoro-icon';
    position: absolute;
    top: 50%;
    transform: translateY(-50%);
    transition: 0.2s ease-in-out;

}

.widget-wrapper:not(.active) p.widget-title:after {
    transform: translateY(-50%) rotate(0);
    transition: 0.2s ease-in-out;
}


.widget-wrapper.active p.widget-title:after {
    transform: translateY(-50%) rotate(135deg);
    transition: 0.2s ease-in-out;
}




